CREATE OR REPLACE FUNCTION private.base_legacy(u uuid, p text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  allowed boolean := false; src jsonb;
  o_mode text; o_perms text[]; o_custom boolean := false;
BEGIN
  IF p LIKE 'biz.crm_%' THEN
    allowed := private.base_crm_legacy(u, p); src := '{"kind":"business","tier":2}';
  ELSIF p LIKE 'biz.%' THEN
    allowed := public.biz_can(u, p); src := '{"kind":"business","tier":2}';
  ELSIF p LIKE 'k3.%' THEN
    allowed := public.k3_can(u, p); src := '{"kind":"business","tier":2}';
  ELSE
    SELECT o.mode, coalesce(o.permissions, '{}') INTO o_mode, o_perms
    FROM user_permission_overrides o WHERE o.user_id = u AND o.use_custom;
    o_custom := FOUND;
    IF o_custom AND o_mode = 'replace' THEN
      allowed := p = ANY(o_perms);
      src := '{"kind":"custom","tier":3}';
    ELSE
      SELECT coalesce(bool_or(p = ANY(r.permissions)), false) INTO allowed
      FROM user_roles ur JOIN app_roles r ON r.id = ur.role_id WHERE ur.user_id = u;
      SELECT jsonb_build_object('kind', 'role', 'tier', 3, 'names', coalesce(jsonb_agg(r.name), '[]')) INTO src
      FROM user_roles ur JOIN app_roles r ON r.id = ur.role_id WHERE ur.user_id = u;
      IF NOT allowed AND o_custom AND o_mode = 'additive' AND p = ANY(o_perms) THEN
        allowed := true;
        src := jsonb_build_object('kind', 'custom', 'tier', 3, 'mode', 'additive');
      END IF;
    END IF;
  END IF;
  RETURN jsonb_build_object('allowed', coalesce(allowed, false), 'source', src);
END $function$

CREATE OR REPLACE FUNCTION private.supplement_permission_guard(u uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN
 IF NOT private.is_active(auth.uid()) OR NOT(private.is_super_admin(auth.uid()) OR (private.is_admin(auth.uid()) AND private.has_permission(auth.uid(),'settings.user_custom_perm'))) THEN RAISE EXCEPTION 'Không có quyền tùy chỉnh quyền nhân sự.';END IF;
 IF u=auth.uid() OR private.is_super_admin(u) OR EXISTS(SELECT 1 FROM profiles WHERE id=u AND is_system_admin) THEN RAISE EXCEPTION 'Tài khoản quản trị và tự thay đổi quyền được bảo vệ.';END IF;
 IF private.cleanup_is_biz_staff(u) AND NOT private.legacy_reset_applies(u) THEN RAISE EXCEPTION 'Tài khoản Kinh doanh chưa chuyển đổi được bảo vệ.';END IF;
 IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=u) THEN RAISE EXCEPTION 'Nhân sự không tồn tại.';END IF;
 END $function$

CREATE OR REPLACE FUNCTION public.att_recall(_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a public.attendance_explanations; _uid uuid := auth.uid();
BEGIN
  SELECT * INTO a FROM public.attendance_explanations WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy giải trình'; END IF;
  IF NOT ((a.owner_id = _uid AND private.sig_can(_uid,'att.edit_own')) OR private.sig_can(_uid,'att.manage')) THEN RAISE EXCEPTION 'Bạn không có quyền thu hồi giải trình này'; END IF;
  IF a.recalled THEN RAISE EXCEPTION 'Giải trình đã thu hồi'; END IF;
  IF a.reconciled AND NOT private.sig_can(_uid,'att.manage') THEN RAISE EXCEPTION 'Giải trình đã được đối chiếu, không thể tự thu hồi'; END IF;
  UPDATE public.attendance_explanations SET recalled=true, recalled_at=now(), updated_at=now() WHERE id=_id;
  INSERT INTO public.attendance_explanation_events(explanation_id, actor_id, action) VALUES (_id, _uid, 'recall');
END $function$

CREATE OR REPLACE FUNCTION public.att_update(_id uuid, _date date, _kind text, _in text, _out text, _reason_id text, _detail text, _witness uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a public.attendance_explanations; _rn text; _uid uuid := auth.uid(); _reset boolean; _old jsonb; _new jsonb;
BEGIN
  SELECT * INTO a FROM public.attendance_explanations WHERE id = _id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy giải trình'; END IF;
  IF NOT ((a.owner_id = _uid AND private.sig_can(_uid,'att.edit_own')) OR private.sig_can(_uid,'att.manage')) THEN RAISE EXCEPTION 'Bạn không có quyền sửa giải trình này'; END IF;
  IF a.recalled THEN RAISE EXCEPTION 'Giải trình đã thu hồi'; END IF;
  IF a.reconciled AND NOT private.sig_can(_uid,'att.manage') THEN RAISE EXCEPTION 'Giải trình đã được đối chiếu, vui lòng liên hệ người quản lý giải trình'; END IF;
  IF _date IS NULL OR _date > (now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN RAISE EXCEPTION 'Ngày quên chấm công không hợp lệ'; END IF;
  PERFORM private.att_check(_kind,_in,_out,_reason_id,_detail,_witness,a.owner_id);
  _rn := private.att_reason_name(_reason_id);
  IF _rn IS NULL THEN RAISE EXCEPTION 'Lý do không hợp lệ'; END IF;
  IF _kind = 'in' THEN _out := NULL; ELSIF _kind = 'out' THEN _in := NULL; END IF;
  _old := jsonb_build_object('work_date',a.work_date,'kind',a.kind,'time_in',a.time_in,'time_out',a.time_out,'reason_name',a.reason_name,'detail',a.detail,'witness_id',a.witness_id);
  _new := jsonb_build_object('work_date',_date,'kind',_kind,'time_in',_in,'time_out',_out,'reason_name',_rn,'detail',nullif(btrim(_detail),''),'witness_id',_witness);
  IF _old = _new THEN RETURN; END IF;
  _reset := a.witness_status <> 'pending' AND (a.work_date <> _date OR a.kind <> _kind OR a.time_in IS DISTINCT FROM _in OR a.time_out IS DISTINCT FROM _out OR a.witness_id <> _witness);
  IF a.witness_id <> _witness THEN _reset := true; END IF;
  UPDATE public.attendance_explanations SET work_date=_date, kind=_kind, time_in=_in, time_out=_out, reason_id=_reason_id, reason_name=_rn,
    detail=nullif(btrim(_detail),''), witness_id=_witness,
    witness_status = CASE WHEN _reset THEN 'pending' ELSE witness_status END,
    witness_at = CASE WHEN _reset THEN NULL ELSE witness_at END,
    witness_note = CASE WHEN _reset THEN NULL ELSE witness_note END,
    updated_at = now() WHERE id = _id;
  INSERT INTO public.attendance_explanation_events(explanation_id, actor_id, action, detail)
  VALUES (_id, _uid, 'edit', jsonb_build_object('old',_old,'new',_new,'witness_reset',coalesce(_reset,false),
    'important', (a.work_date <> _date OR a.kind <> _kind OR a.time_in IS DISTINCT FROM _in OR a.time_out IS DISTINCT FROM _out OR a.witness_id <> _witness)));
END $function$

CREATE OR REPLACE FUNCTION public.k3_can(_actor uuid, _permission text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ BEGIN
 IF NOT private.is_active(_actor) THEN RETURN false; END IF;
 IF public.is_super_admin(_actor) OR public.biz_admin(_actor) THEN RETURN true; END IF;
 IF private.k3_personal_denied(_actor,_permission) THEN RETURN false; END IF;
 IF _permission='k3.use' THEN RETURN true; END IF;
 IF NOT private.legacy_business_allowed(_actor) THEN RETURN false; END IF;
 IF _permission IN ('k3.view_scope','k3.comment') THEN RETURN public.biz_manager(_actor) OR public.biz_all_scope(_actor); END IF;
 RETURN false; END $function$

CREATE OR REPLACE FUNCTION public.leave_update(_id uuid, _payload jsonb, _reason_id text, _detail text, _approver uuid, _exception text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE uid uuid := auth.uid(); q public.leave_requests; p jsonb;
BEGIN
  SELECT * INTO q FROM public.leave_requests WHERE id = _id FOR UPDATE;
  IF q.id IS NULL THEN RAISE EXCEPTION 'Không tìm thấy đơn.'; END IF;
  IF NOT ((q.owner_id = uid AND private.sig_can(uid,'leave.edit_own')) OR private.sig_can(uid,'leave.edit_others')) THEN RAISE EXCEPTION 'Bạn không có quyền sửa đơn này.'; END IF;
  IF q.status <> 'pending' THEN RAISE EXCEPTION 'Chỉ sửa được đơn đang Chờ duyệt.'; END IF;
  p := private.leave_prepare(q.owner_id, q.type, _payload, _reason_id, _detail, _approver, _exception);
  PERFORM private.leave_log(_id, 'edit', jsonb_build_object('before', jsonb_build_object('payload', q.payload, 'reason', q.reason_name, 'detail', q.detail, 'approver', q.approver_id, 'calc', q.calc, 'is_late', q.is_late, 'late_reason', q.late_reason)));
  UPDATE public.leave_requests SET payload = _payload, calc = p->'calc', mark_at = (p->'calc'->>'mark_at')::timestamptz, applied = p->'applied',
    reason_id = _reason_id, reason_name = p->>'reason_name', detail = nullif(btrim(_detail),''), approver_id = _approver,
    is_late = (p->>'exception')::boolean, late_reason = CASE WHEN (p->>'exception')::boolean THEN btrim(_exception) END, updated_at = now() WHERE id = _id;
  UPDATE public.leave_request_submissions SET payload = _payload, calc = p->'calc', reason_id = _reason_id, reason_name = p->>'reason_name',
    detail = nullif(btrim(_detail),''), approver_id = _approver,
    is_late = (p->>'exception')::boolean, late_reason = CASE WHEN (p->>'exception')::boolean THEN btrim(_exception) END WHERE request_id = _id AND no = q.submission_no;
END $function$
